// Optional asset maintenance: SHARP_MODULE=/path/to/sharp npm run images
// Generated files are committed, so normal builds do not require Sharp.
import { createRequire } from 'node:module'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { basename, extname } from 'node:path'
import { events } from '../src/data/events.js'
import { blogPosts, blogAuthors } from '../src/data/blog.js'
const sharp = createRequire(import.meta.url)(process.env.SHARP_MODULE || 'sharp')
const sources = [...new Set([
  ...events.map(event => event.image), ...blogPosts.map(post => post.featuredImage),
  ...Object.values(blogAuthors).map(author => author.image),
  '/img/leicester-aikikai-antonios-pavlakis-2016.jpg',
  '/img/leicester-aikikai-bokken-shiko-dachi-circle-exercise.webp',
  '/img/antonis-pavlakis-with-iain-cooper.webp',
  '/img/aylestone-leisure-centre-mat-space.jpeg',
  '/img/leicester-aikikai-aylestone-leisure-centre.jpeg',
  '/img/leicester-aikikai-joint-course-march-17th-2024.webp',
  '/img/leicester-aikikai-dojo-hall.jpg'
].filter(Boolean))]
mkdirSync('public/img/optimised', { recursive: true })
const manifest = {}
let before = 0, after = 0
for (const source of sources) {
  const original = readFileSync(`public${source}`)
  const normalised = await sharp(original).rotate().toBuffer()
  const metadata = await sharp(normalised).metadata()
  const hash = createHash('sha256').update(original).update('web-images-v1-q86').digest('hex').slice(0, 10)
  const name = basename(source, extname(source)).toLowerCase().replace(/[^a-z0-9-]+/g, '-')
  const widths = [...new Set([320, 640, 960, Math.min(1280, metadata.width)].filter(width => width <= metadata.width))].sort((a,b) => a-b)
  const variants = []
  for (const width of widths) {
    const path = `/img/optimised/${name}-${hash}-${width}.webp`
    const result = await sharp(normalised).resize({ width, withoutEnlargement:true }).webp({quality:86,effort:6}).toFile(`public${path}`)
    variants.push({path,width:result.width,height:result.height,bytes:result.size})
  }
  // Keep an already efficient original when conversion would increase transfer size.
  let largest = variants.at(-1)
  if (metadata.width === largest.width && original.length < largest.bytes && !metadata.orientation) {
    largest = { ...largest, path: source, bytes: original.length }
    variants[variants.length - 1] = largest
  }
  const social = `/img/optimised/${name}-${hash}-social.jpg`
  const socialInfo = await sharp(normalised).resize({width:1200,height:1200,fit:'inside',withoutEnlargement:true}).flatten({background:'#fff'}).jpeg({quality:84,mozjpeg:true}).toFile(`public${social}`)
  manifest[source] = {src:largest.path,srcset:variants.map(item => `${item.path} ${item.width}w`).join(', '),width:largest.width,height:largest.height,social,socialWidth:socialInfo.width,socialHeight:socialInfo.height}
  before += original.length
  after += largest.bytes
  console.log(`${source}: ${original.length} → ${largest.bytes} bytes`)
}
const aliases = {
  '/img/training-1280.webp':'/img/leicester-aikikai-aylestone-leisure-centre.jpeg',
  '/img/training-960.webp':'/img/leicester-aikikai-aylestone-leisure-centre.jpeg',
  '/img/instructor-800.webp':'/img/leicester-aikikai-antonios-pavlakis-2016.jpg',
  '/img/venue-960.webp':'/img/aylestone-leisure-centre-mat-space.jpeg',
  '/img/community-1280.webp':'/img/leicester-aikikai-joint-course-march-17th-2024.webp'
}
for (const [alias,source] of Object.entries(aliases)) manifest[alias] = manifest[source]
writeFileSync('src/data/images.js', `// Generated by scripts/optimise-images.mjs; originals remain in public/img.\nexport const images = ${JSON.stringify(manifest,null,2)}\n`)
console.log(`Largest web variants: ${before} → ${after} bytes (${Math.round((1-after/before)*100)}% smaller across ${sources.length} sources).`)
